class Hotel:
    def __init__(self, name, rooms):
        self.name = name
        self._available_rooms = rooms
        self._booked_rooms = {}

    @property
    def available_rooms(self):
        return self._available_rooms

    @property
    def booked_rooms(self):
        return self._booked_rooms

    def book_room(self, room_type, room_number, name):
        if room_type not in self.available_rooms:
            return False

        if room_number <= self.available_rooms[room_type]:
            self._book_room(room_type, room_number, name)
            return "Success!"
        elif self.available_rooms[room_type] != 0:
            return self.available_rooms[room_type]
        else:
            return False

    def _book_room(self, room_type, room_number, name):
        if room_type not in self.booked_rooms:
            self._booked_rooms[room_type] = {}
        self._booked_rooms[room_type][name] = room_number
        self._available_rooms[room_type] -= room_number

    def check_in(self, room_type, room_number, name):
        if room_type not in self.booked_rooms:
            return False
        if name in self.booked_rooms[room_type]:
            self._process_check_in(room_type, room_number, name)

    def _process_check_in(self, room_type, room_number, name):
        booked_room_number = self.booked_rooms[room_type][name]
        if room_number > booked_room_number:
            return False
        elif room_number == booked_room_number:
            self._booked_rooms[room_type].pop(name)
        else:
            self._booked_rooms[room_type][name] = booked_room_number - room_number

    def check_out(self, room_type, room_number):
        self._add_available_rooms(room_type, room_number)

    def _add_available_rooms(self, room_type, room_number):
        if room_type in self._available_rooms:
            self._available_rooms[room_type] += room_number
        else:
            self._available_rooms[room_type] = room_number

    def get_available_rooms(self, room_type):
        return self._available_rooms[room_type]
